# Convert rows to JSON and CSV formats
years = ["y2024", "y2023", "y2022", "y2021", "y2020", "y2019", "y2018", "y2017", "y2016", "y2015", "y2014", "y2013", "y2012", "y2011"]

for r in raw_rows:
    cat, mfr, mdl, bdy, vals = r
    row_dict = {
        "category": cat,
        "manufacturer": mfr,
        "model": mdl,
        "body": bdy
    }
    for idx, yr_key in enumerate(years):
        v = vals[idx]
        row_dict[yr_key] = f"₹ {v:.2f} L" if v > 0 else "—"
    data["rows"].append(row_dict)

# Write JSON to app assets
with open("app/src/main/assets/data/cv_grid.json", "w", encoding="utf-8") as f:
    json.dump(data, f, indent=2, ensure_ascii=False)

# Write JSON to CV Grid/
with open("CV Grid/cv_grid.json", "w", encoding="utf-8") as f:
    json.dump(data, f, indent=2, ensure_ascii=False)

# Write CSV to CV Grid/
with open("CV Grid/cv_grid.csv", "w", newline="", encoding="utf-8") as f:
    writer = csv.writer(f)
    writer.writerow(["Category", "Manufacturer", "Model", "Body Type", "2024 (1Y)", "2023 (2Y)", "2022 (3Y)", "2021 (4Y)", "2020 (5Y)", "2019 (6Y)", "2018 (7Y)", "2017 (8Y)", "2016 (9Y)", "2015 (10Y)", "2014 (11Y)", "2013 (12Y)", "2012 (13Y)", "2011 (14Y)"])
    for r in data["rows"]:
        writer.writerow([r["category"], r["manufacturer"], r["model"], r["body"]] + [r[y] for y in years])

print(f"Successfully exported {len(data['rows'])} CV grid models.")
